mapper.select:
SELECT regin.user_code,regin.`name`,regin.user_name,regin.gender,regin.birth_date,regin.Org_Code,org.Org_Name,org.Super_Org_Code,enro.Flag_Dgroup, ( SELECT count(1) FROM yh_template_detail WHERE user_code = regin.user_code AND execute_date >= (SELECT now()) ) AS plan_count ,exe.last_plan_time, (SELECT COUNT(*) from yh_user_reginfo regin LEFT JOIN yh_user_make_card makecard ON regin.user_code=makecard.User_Code LEFT JOIN yh_org_tree org ON regin.Org_Code=org.Org_Code LEFT JOIN yh_user_enrolinfo enro ON regin.user_code=enro.user_code LEFT JOIN yh_template_execution exe ON regin.user_code=exe.user_code
WHERE makecard.doctor=(SELECT id FROM yh_user_admin_info WHERE User_Code=#{user_code})
and regin.gender = #{gender}
and org.Org_Code = #{Org_Code}
and enro.Flag_Dgroup LIKE CONCAT('%',#{dis},'%')
and enro.Flag_Dgroup LIKE CONCAT('%',#{manageli},'%')
AND exe.plan_count >0
AND exe.plan_count IS NULL
AND regin.birth_date <= #{minage}
AND regin.birth_date >= #{maxage}
and regin.name LIKE CONCAT('%',#{name},'%')
) AS count from yh_user_reginfo regin LEFT JOIN yh_user_make_card makecard ON regin.user_code=makecard.User_Code LEFT JOIN yh_org_tree org ON regin.Org_Code=org.Org_Code LEFT JOIN yh_user_enrolinfo enro ON regin.user_code=enro.user_code LEFT JOIN yh_template_execution exe ON regin.user_code=exe.user_code
WHERE makecard.doctor=(SELECT id FROM yh_user_admin_info WHERE User_Code=#{user_code})
and regin.gender = #{gender}
and org.Org_Code = #{Org_Code}
and enro.Flag_Dgroup LIKE CONCAT('%',#{dis},'%')
and enro.Flag_Dgroup LIKE CONCAT('%',#{manageli},'%')
AND exe.plan_count >0
AND exe.plan_count IS NULL
AND regin.birth_date <= #{minage}
AND regin.birth_date >= #{maxage}
and regin.name LIKE CONCAT('%',#{name},'%')
LIMIT #{page},#{limit}

